-- ─────────────────────────────────────────────────────────────
--  THE OLD WEBSITE'S NEWS — part 2 of 7: 59 articles that go live
--  Generated by scripts/import-old-news.py from Rich's export of the old WordPress database.
--  Run the news files in order, after the other files in supabase/legacy/ (SQL Editor → paste → Run), each once.
--
--  All 528 old articles: 186 league and competition articles from 2019 on go live, with their real dates.
--  The other 342 wait in Admin → News as drafts (Rich, round 30): Professional Snooker, CueViews,
--  Snooker Memories, and the old archive — whose articles all carry the date 1 January 2014 on the old site
--  (their real dates were lost long ago). Tick "Published" on any of them to put it on the website.
--  The text keeps its paragraphs, the opening paragraph and the pull quote. Pictures are not brought across
--  (Rich is sorting them): real-data/legacy/news-pictures.csv says which article had which picture.
--  None is "featured", so the News page and the banner keep showing the newest articles.
--  Nothing already on the website is changed. All one transaction.
-- ─────────────────────────────────────────────────────────────
begin;

do $$ begin
  if exists (select 1 from articles where slug in ('league-leaders-bugle-a-suffer-shock-defeat', 'bethel-a-moving-up-the-table', 'bethel-a-close-in-to-victory-leaders-bugle-a', 'fantastic-5-and-big-breaks-for-bugle-a-as-they-whitewash-the-champions', 'latest-from-the-2024-25-team-pairs-competition')) then
    raise exception 'This part of the old news is already in: nothing to do.';
  end if;
end $$;

insert into categories (name, sort)
  select r.name, 100 + row_number() over (order by r.name) from (values
  ('Competitions'),
  ('Cue View'),
  ('League Meetings'),
  ('League News'),
  ('Match Reports'),
  ('Professional Snooker'),
  ('Snooker Memories')) r(name)
  where not exists (select 1 from categories c where lower(c.name) = lower(r.name));

create temp table _news (title text, slug text, category text, more_categories jsonb, excerpt text, lead text, quote_text text, body text, published_at date, is_published boolean, author text) on commit drop;
insert into _news values
  ('League leaders Bugle A suffer shock defeat', 'league-leaders-bugle-a-suffer-shock-defeat', 'Match Reports', '[]'::jsonb, 'The Victory League leaders Bugle A suffered a 3 2 home defeat against Bethel D', 'The Victory League leaders Bugle A suffered a 3-2 home defeat against Bethel D', 'Mevagissey A moved joint top of the Rees league after beating St Blazey B 4-1', 'The visitors went 3 up through Geoff Hawken, Paul Baron who made a 25 clearance to defeat Andrew Best and Steve Benallack with Gary Spencer and Josh Bristow pulling back the final 2 frames.

Bethel A beat St Blazey A taking all 5 frames which was hard to take for the Blazey boys with 2 black ball frames going the way of the Defending champions.

St Neot won by the odd frame at Tregonissey A with Darren Lock needing all of his 44 break to defeat Ryan Bilson there were also victories for Ant Maddams and Steve Courts who beat on the Black with Harrison Burdon and Jason Cocks getting the home points.

And Mevagissey B great season continues taking 4 frames at home to Tregonissey B with Chris Stephenson beating Nathan Shaw for the away team.

Mevagissey A moved joint top of the Rees league after beating St Blazey B 4-1 joining there opponents at the summit. Rich Lakeman, Ben Prynn and 2 wins for Darren Powell got there wins with Kyle Masters replying.

Mevagissey C are 3rd after beating Lerryn by the odd frame Benjamin Baker and Richard Tamblin put them 2 up but Les Shakespeare and James Stephens levelled up with Adrian Evans taking out Terry Middleton in the finale.

Dan Pascoe and Warren Ball got Gorran Haven 2 points at home to Bugle B who replied through Keith Moore and Colin and Dave Rundle.

Roger Smithson and Leigh Rosevears very low scoring win over Darren Elliott put Bethel C in front at home to Tregonissey C but Predator Tregale and Jowan Truman squared things up but Howard Brett''s win over the Predator who was playing his 2nd game got the win.

44

